static void sbuf_append(const char *text)
{
    size_t tlen = strlen(text);
    if (g_sbuf_len + tlen + 2 > g_sbuf_cap) {
        g_sbuf_cap = (g_sbuf_cap + tlen + 8192) * 2;
        g_sbuf = realloc(g_sbuf, g_sbuf_cap);
    }
    memcpy(g_sbuf + g_sbuf_len, text, tlen);
    g_sbuf_len += tlen;
    g_sbuf[g_sbuf_len] = '\0';
}

