static void strip_ansi(const char *src, char *dst, size_t cap)
{
    size_t di = 0;
    for (size_t si = 0; src[si] && di + 1 < cap; si++) {
        if (src[si] == '\033' && src[si+1] == '[') {
            si += 2;
            while (src[si] && src[si] != 'm') si++;
        } else {
            dst[di++] = src[si];
        }
    }
    dst[di] = '\0';
}

