void monad_destroy(Monad *m)
{
    if (!m) return;
    free(m->zeros); free(m->beta); free(m->age); free(m->vocab);
    for (int i = 0; i < m->wm_cap; i++) if (m->wm[i].key) free(m->wm[i].key);
    free(m->wm); free(m->am);
    free(g_sbuf); g_sbuf = NULL; g_sbuf_len = g_sbuf_cap = 0;
    free(m);
}

