        read32(f, &word_count) || read64d(f, &threshold)) {
        fprintf(stderr, "[state] header read error\n");
        fclose(f); return -1;
    }

    if ((int)N != m->N) {
        fprintf(stderr, "[state] vocab load: N mismatch — file=%u monad=%d\n", N, m->N);
