    }

    /* v4: affect — present but we leave m->affect untouched */
    if (version >= 4) {
        float af;
        if (fread(&af, sizeof(float), 1, f) != 1) {
            fprintf(stderr, "[state] affect read error\n");
            fclose(f); return -1;
