    for (int i = 0; i < m->wm_cap; i++) {
        if (m->wm[i].key) { free(m->wm[i].key); m->wm[i].key = NULL; }
        m->wm[i].idx = 0;
    }
    m->wm_size = 0;

    /* Read vocab entries — identical to state_load vocab loop */
    for (uint32_t i = 0; i < vocab_size; i++) {
        uint32_t idx;
        uint16_t wlen;
        double   E;
        if (read32(f, &idx) || read16(f, &wlen) || read64d(f, &E)) {
