static int is_pure_numeric(const char *s)
{
    if (!*s) return 0;
    for (; *s; s++)
        if (*s < '0' || *s > '9') return 0;
    return 1;
}

C:filter.c:is_hex_string:
static int is_hex_string(const char *s, size_t len)
{
    /* 0x... prefix */
    if (len >= 3 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) return 1;
    /* All chars are hex digits and length suggests encoded data */
    if (len < 6) return 0;
    for (size_t i = 0; i < len; i++) {
        char c = s[i];
        if (!((c >= '0' && c <= '9') ||
              (c >= 'a' && c <= 'f') ||
              (c >= 'A' && c <= 'F'))) return 0;
    }
    return 1;
}

C:filter.c:is_uuid:
static int is_uuid(const char *s, size_t len)
{
    if (len != 36) return 0;
    static const int dash_pos[] = {8, 13, 18, 23, -1};
    for (int i = 0; i < 36; i++) {
        int is_dash = 0;
        for (int d = 0; dash_pos[d] >= 0; d++)
            if (dash_pos[d] == i) { is_dash = 1; break; }
        if (is_dash) { if (s[i] != '-') return 0; continue; }
        char c = s[i];
        if (!((c >= '0' && c <= '9') ||
              (c >= 'a' && c <= 'f') ||
              (c >= 'A' && c <= 'F'))) return 0;
    }
    return 1;
}

C:filter.c:is_base64_chunk:
static int is_base64_chunk(const char *s, size_t len, int min_len)
{
    if ((int)len < min_len) return 0;
    if (s[len - 1] != '=') return 0;
    int ok = 0;
    for (size_t i = 0; i < len; i++) {
        char c = s[i];
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
            (c >= '0' && c <= '9') || c == '+' || c == '/' || c == '=')
            ok++;
    }
    return ok * 100 / (int)len >= 95;
}

C:filter.c:vowel_count:
static int vowel_count(const char *s)
{
    int n = 0;
    for (; *s; s++) {
        char c = *s | 0x20;  /* to lower */
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') n++;
    }
    return n;
}

C:filter.c:high_digit_ratio:
static int high_digit_ratio(const char *s, size_t len)
{
    if (!len) return 0;
    int d = 0;
    for (size_t i = 0; i < len; i++)
        if (s[i] >= '0' && s[i] <= '9') d++;
    return d * 100 / (int)len > 50;
}

C:filter.c:is_long_allcaps:
static int is_long_allcaps(const char *s, size_t len)
{
    if (len <= 6) return 0;
    for (size_t i = 0; i < len; i++) {
        char c = s[i];
        if (c == '_') continue;
        if (c >= 'A' && c <= 'Z') continue;
        if (c >= '0' && c <= '9') continue;
        return 0;
    }
    return 1;
}

C:filter.c:token_accept:
int token_accept(const char *tok, NSFiletype ft)
{
    size_t len = strlen(tok);
    const FTRules *r = rules_for(ft);

    /* ── Universal gates (all filetypes) ─────────────────────────────────── */

    if (len < 2)                          return 0;  /* single char          */
    if ((int)len > r->max_len)            return 0;  /* too long             */
    if (is_pure_numeric(tok))             return 0;  /* 12345                */
    if (is_uuid(tok, len))                return 0;  /* UUID                 */
    if (strchr(tok, '='))                 return 0;  /* key=value            */
    if (strstr(tok, "://"))               return 0;  /* URL fragment         */

    /* ── Filetype-conditional gates ──────────────────────────────────────── */

    if (!r->allow_hex && is_hex_string(tok, len))           return 0;
    if (!r->allow_slash && strchr(tok, '/'))                return 0;
    if (!r->allow_slash && strchr(tok, '\\'))               return 0;
    if (!r->allow_high_dig && high_digit_ratio(tok, len))   return 0;
    if (!r->allow_long_caps && is_long_allcaps(tok, len))   return 0;
    if (r->b64_min_len > 0 && is_base64_chunk(tok, len, r->b64_min_len))
        return 0;

    /* ── Vowel gate (prose/markup/doc) ──────────────────────────────────────── */

    if (r->require_vowel) {
        int vc = vowel_count(tok);
        if (vc == 0)                                         return 0;
        /* Very low vowel ratio in longer tokens: "wlvfe", "schzr", etc. */
        if ((int)len >= 6 && vc * 100 / (int)len < 15)      return 0;
    }

    /* Trailing apostrophe fragment: "pins'", "ban'" */
    if (tok[len - 1] == '\'')                               return 0;

    return 1;
}

C:main.c:run_eval:
static void run_eval(const char *ckpt_path)
{
    /* Locate eval_checkpoint.py: SMMIP_REPO env → default path → skip */
    char script[4096] = {0};
    const char *smmip = getenv("SMMIP_REPO");
    if (smmip && smmip[0]) {
        snprintf(script, sizeof(script), "%s/tools/eval_checkpoint.py", smmip);
    } else {
        const char *home = getenv("HOME");
        if (home && home[0])
            snprintf(script, sizeof(script),
                     "%s/Projects/Ptol/SMMIP/tools/eval_checkpoint.py", home);
    }
    if (!script[0]) return;

    FILE *t = fopen(script, "r");
    if (!t) return;
    fclose(t);

    /* Write JSON assessment alongside checkpoint */
    char json_out[4096];
    snprintf(json_out, sizeof(json_out), "%s.assessment.json", ckpt_path);

    char cmd[8192];
    snprintf(cmd, sizeof(cmd),
             "python3 '%s' '%s' --out '%s'", script, ckpt_path, json_out);

    fprintf(stderr, "\n[eval] running checkpoint assessment...\n");
    int rc = system(cmd);
    if (rc == 0)
        fprintf(stderr, "[eval] assessment written → %s\n", json_out);
    else if (rc > 0)
        fprintf(stderr, "[eval] verdict: WARN/FAIL (exit %d) — see %s\n", rc, json_out);
}

